import { readFileSync } from 'node:fs';

/** The manifest is generated by scripts/generate-index-metadata.mjs; check what that script writes. */
describe('PWA manifest source', () => {
  const script = readFileSync('scripts/generate-index-metadata.mjs', 'utf8');

  it('FIL-019 registers a PDF file handler', () => {
    expect(script).toContain("file_handlers: [{ action: './', accept: { 'application/pdf': ['.pdf'] } }]");
  });

  it('FIL-019 focuses the running window for further launches', () => {
    expect(script).toContain("launch_handler: { client_mode: 'focus-existing' }");
  });
});
